8	import 'package:cerne/core/failure/failure.dart';
9	import 'package:cerne/core/widgets/back_arrow_header.dart';
10	import 'package:cerne/features/account/domain/repositories/account_settings_repository.dart';
11	import 'package:cerne/features/account/presentation/cubit/account_settings_cubit.dart';
12	import 'package:cerne/features/account/presentation/screens/account_settings_screen.dart';
13	import 'package:cerne/features/dashboard/domain/entities/dashboard_aggregate.dart';
14	import 'package:cerne/features/dashboard/domain/repositories/dashboard_repository.dart';
15	import 'package:cerne/features/dashboard/presentation/cubit/dashboard_cubit.dart';
16	import 'package:cerne/features/dashboard/presentation/widgets/dashboard_chart_section.dart';
17	import 'package:cerne/features/entries/domain/entities/entry.dart';
18	import 'package:cerne/features/entries/domain/entities/pending_entry_write.dart';
19	import 'package:cerne/features/entries/domain/services/pending_entry_write_tracker.dart';
20	
21	/// Same plain (non-mocktail) fake shape as
22	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
23	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
24	/// real stream the cubit (built from this fake, not mocked) actually
25	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
26	/// a `Stream.multi` replay wrapper (unlike the production repository) —
27	/// `AccountSettingsCubit`'s own constructor already reads
28	/// [currentBiometricEnabled] directly for its initial state, so no replay
29	/// machinery is needed for a fake with exactly one subscriber.
30	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
31	  bool _value = true;
32	  final _controller = StreamController<bool>.broadcast();
33	
34	  /// The next `setBiometricEnabled()` call's own result — defaults to a
35	  /// failure so a test must opt in to the success path explicitly, same
36	  /// convention as the cubit-level fake.
37	  Either<Failure, Unit> setBiometricEnabledResult = left(
38	    const Failure.malformedResponse(message: 'fake: not configured'),
39	  );
40	
41	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
42	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
43	  /// disable itself while a toggle is in flight).
44	  Completer<void>? setBiometricEnabledGate;
45	
46	  @override
47	  bool get currentBiometricEnabled => _value;
48	
49	  @override
50	  Stream<bool> get biometricEnabledStream => _controller.stream;
51	
52	  @override
53	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
54	
55	  @override
56	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
57	    final gate = setBiometricEnabledGate;
58	    if (gate != null) {
59	      await gate.future;
60	    }
61	    final previous = _value;
62	    _emit(enabled);
63	    final result = setBiometricEnabledResult;
64	    if (result.isLeft()) {
65	      _emit(previous);
66	    }
67	    return result;
68	  }
69	
70	  @override
71	  Future<void> dispose() => _controller.close();
72	
73	  void _emit(bool value) {
74	    _value = value;
75	    _controller.add(value);
76	  }
77	}
78	
79	/// spec-8-1 — a trivial fake [DashboardRepository]: this suite only needs
80	/// `AccountSettingsScreen.initState`'s own unconditional `dashboardCubit.
81	/// load()` call to resolve without throwing (`dashboard_cubit_test.dart`/
82	/// `dashboard_chart_section_test.dart` already cover the chart's own
83	/// behavior in isolation) — defaults to the zero-entries shape.
84	class _FakeDashboardRepository implements DashboardRepository {
85	  Either<Failure, DashboardAggregate> getAggregateResult = right(
86	    const DashboardAggregate(totalCount: 0, bucketCounts: []),
87	  );
88	
89	  @override
90	  Future<Either<Failure, DashboardAggregate>> getAggregate({
91	    required String period,
92	  }) async => getAggregateResult;
93	}
94	
95	/// A trivial fake `PendingEntryWriteTracker` — this suite never exercises
96	/// spec-8-1's own `confirmedWrites` recompute path, only that
97	/// `DashboardCubit`'s constructor subscription resolves without throwing.
98	class _UnusedPendingEntryWriteTracker implements PendingEntryWriteTracker {
99	  @override
100	  Future<Either<Failure, Entry>> create({
101	    required String content,
102	    required EntrySource source,
103	    int? mediaDurationSeconds,
104	  }) async => throw UnimplementedError('not expected to be called');
105	
106	  @override
107	  Future<void> retry(String tempId) async =>
108	      throw UnimplementedError('not expected to be called');
109	
110	  @override
111	  Stream<List<PendingEntryWrite>> get pendingWrites => const Stream.empty();
112	
113	  @override
114	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
115	      const Stream.empty();
116	
117	  @override
118	  Future<void> dispose() async {}
119	}
120	
121	/// Builds a fresh [DashboardCubit] and registers it for teardown — every
122	/// test below needs one to satisfy `AccountSettingsScreen`'s widened
123	/// constructor (spec-8-1), even the ones that otherwise only exercise the
124	/// biometric toggle. [repository] defaults to a fresh
125	/// [_FakeDashboardRepository] (the zero-entries shape); a caller that needs
126	/// to configure [_FakeDashboardRepository.getAggregateResult] *before*
127	/// `AccountSettingsScreen.initState`'s own `load()` call fires (review
128	/// finding: proving that call actually happens, not just that it doesn't
129	/// throw) passes its own instance in instead.
130	DashboardCubit _buildDashboardCubit({DashboardRepository? repository}) {
131	  final cubit = DashboardCubit(
132	    repository ?? _FakeDashboardRepository(),
133	    _UnusedPendingEntryWriteTracker(),
134	  );
135	  addTearDown(() => cubit.close());
136	  return cubit;
137	}
138	
139	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
140	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
141	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
142	/// rather than a bare `MaterialApp`.
143	GoRouter _routerWith(Widget screen) {
144	  return GoRouter(
145	    initialLocation: '/configuracoes',
146	    routes: [
147	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
148	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
149	    ],
150	  );
151	}
152	
153	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
154	/// pair and pumps the real screen around it, registering both for cleanup.
155	///
156	/// Deliberately constructed *inside* each `testWidgets` body (via this
157	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
158	/// `package:test`'s own per-test zone, a different zone than the one
159	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
160	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
161	/// subscription to the repository's stream, set up in its constructor)
162	/// created in that outer zone does not reliably get its pending events
163	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
164	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
165	/// widget never rebuilt, no matter how many `pump()` calls followed.
166	/// Constructing the cubit here, inside the same zone `tester.pump()`
167	/// drains, avoids the mismatch entirely.
168	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
169	  WidgetTester tester,
170	) async {
171	  final fakeRepository = _FakeAccountSettingsRepository();
172	  final cubit = AccountSettingsCubit(fakeRepository);
173	  addTearDown(() => cubit.close());
174	  addTearDown(fakeRepository.dispose);
175	
176	  final router = _routerWith(
177	    AccountSettingsScreen(cubit: cubit, dashboardCubit: _buildDashboardCubit()),
178	  );
179	  addTearDown(router.dispose);
180	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
181	
182	  return (fakeRepository, cubit);
183	}
184	
185	/// Proves spec-2-4's Acceptance Criteria directly against the real screen
186	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
187	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
188	/// toggle's error message renders inline — `app_router_test.dart` already
189	/// proves the screen is *reachable*; this suite proves its own rendering
190	/// and interaction in isolation.
191	void main() {
192	  testWidgets(
193	    // Review finding (round 2): renamed from "...exactly one switch — no '
194	    // other content (AC: shows only the biometric toggle)" — spec-8-1 now
195	    // also renders the "Sua evolução" chart section on this same screen,
196	    // so that title no longer reflects what the screen actually shows.
197	    'shows the biometric toggle and the dashboard chart section',
198	    (tester) async {
199	      await _pumpScreen(tester);
200	
201	      expect(find.byType(BackArrowHeader), findsOneWidget);
202	      expect(find.text('Configurações'), findsOneWidget);
203	      expect(find.byType(Switch), findsOneWidget);
204	      expect(find.text('Entrar com biometria'), findsOneWidget);
205	      expect(find.text('Sua evolução'), findsOneWidget);
206	    },
207	  );
208	
209	  testWidgets(
210	    'the switch mirrors currentBiometricEnabled (true) at construction',
211	    (tester) async {
212	      await _pumpScreen(tester);
213	
214	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
215	      expect(switchWidget.value, isTrue);
216	    },
217	  );
218	
