      const DashboardAggregate(totalCount: 1, bucketCounts: [1]),
    );
    await cubit.load();
    await tester.pump();

    expect(
      find.text('Comece a registrar para ver sua evolução aqui'),
      findsNothing,
    );
    expect(find.byType(DashboardChartBar), findsOneWidget);
  });
}

