6	import 'domain/repositories/dashboard_repository.dart';
7	import 'presentation/cubit/dashboard_cubit.dart';
8	
9	/// Registers the `dashboard` feature into the project's single `get_it`
10	/// instance (`sl`) — mirrors `export_injection.dart`'s own shape. Must run
11	/// after `registerEntriesFeature()` (`injection_container.dart`'s own call
12	/// order, Code Map) since [DashboardCubit] depends on the shared
13	/// [PendingEntryWriteTracker] that registration provides. No Hive box here
14	/// (Boundaries/Never: "cache the aggregate", AD-15 exclusion).
15	void registerDashboardFeature() {
16	  sl.registerLazySingleton<DashboardRemoteDataSource>(
17	    () => DashboardRemoteDataSource(sl<ApiClient>()),
18	  );
19	
20	  sl.registerLazySingleton<DashboardRepository>(
21	    () => DashboardRepositoryImpl(
22	      remoteDataSource: sl<DashboardRemoteDataSource>(),
23	    ),
24	  );
25	
26	  // Boundaries — a `registerLazySingleton`, not a factory: long-lived, so
27	  // its constructor subscription to `PendingEntryWriteTracker.
28	  // confirmedWrites` stays live for the app's whole session (same
29	  // rationale `MeusRegistrosCubit`'s own registration gives). `dispose:`
30	  // wires `close()` into `get_it`'s own reset lifecycle, same convention
31	  // every other long-lived cubit in this project already uses.
32	  sl.registerLazySingleton<DashboardCubit>(
33	    () => DashboardCubit(
34	      sl<DashboardRepository>(),
35	      sl<PendingEntryWriteTracker>(),
36	    ),
37	    dispose: (cubit) => cubit.close(),
38	  );
39	}
